    eyebrow: "استلام وتوصيل مجاني من السالمية • الإصلاح في مختبر KCROC بحولي",
    intro: "تدور فني كمبيوتر أو لابتوب في السالمية؟ ما تحتاج تروح حولي بنفسك: نستلم الجهاز من بيتك أو مكتبك في السالمية، نشخصه ونصلحه في مختبرنا في مجمع الملا بحولي، وبعد الفحص والاختبار نرجعه لك. نخدم السالمية والرميثية وسلوى والبدع بنفس الخدمة المجانية.",
    bullets: ["استلام وتوصيل مجاني من السالمية والرميثية وسلوى والبدع", "تشخيص العطل قبل أي إصلاح", "معالجة أضرار السوائل على مستوى المكونات", "تصليح لابتوب وMacBook واللوحة الأم", "ضمان 30 يومًا على الإصلاح المكتمل"],
