      { q: "هل الاستلام من الجهراء مجاني رغم المسافة؟", a: "نعم، الاستلام والتوصيل مجاني من الجهراء وسعد العبدالله والنعيم والقصر وتيماء. المسافة إلى حولي علينا مو عليك." },
      { q: "لابتوب الجيمنج يسخن وصوت المراوح عالي، شنو أسوي؟", a: "أوقف الاستخدام الثقيل، وحط اللابتوب على سطح صلب مستوي، وتأكد إن فتحات التهوية مو مسدودة بالغبار. الغبار وجفاف المعجون الحراري من أكثر الأسباب شيوعًا. ننظف المراوح والمشتت ونبدل المعجون ونفحص التبريد قبل أي شيء ثاني." },
      { q: "اللابتوب يطفي لحاله تحت الضغط، هل السبب سخونة أو عطل في اللوحة؟", a: "ممكن الاثنين. الإطفاء بسبب السخونة حماية للجهاز، وعطل دائرة الطاقة ممكن يعطي نفس العرض. نفحص الحرارة تحت الحمل أول، وبعدها نختبر مسار الطاقة على الطاولة قبل ما نقترح أي إصلاح على اللوحة." },
      { q: "كم سعر تصليح اللابتوب لعملاء الجهراء؟", a: "الفحص مجاني. الإصلاحات الشائعة للابتوب تبدأ من 15 د.ك، وتبديل الشاشة من 30 د.ك، وإصلاح اللوحة الأم على مستوى المكونات من 25 د.ك، والسعر النهائي يعتمد على الجهاز والعطل والقطعة المطلوبة. تعرف السعر قبل أي عمل مدفوع، وإذا ما قدرنا نصلح الجهاز ما تدفع شيء." },
      { q: "كم تاخذ مدة الإصلاح؟", a: "كثير من الإصلاحات تخلص خلال 24-48 ساعة من استلام الجهاز، وإصلاح اللوحة الأم عادة 24-72 ساعة، وبعض الشاشات والبطاريات ممكن في نفس اليوم إذا القطعة متوفرة. نعطيك تقديرًا واقعيًا بعد الفحص لأن نوع العطل وتوفر القطع يحددان الوقت." }
